def allow_cancel(age_seconds, until_start_seconds):
    # 10분을 초로 변환
    correction_time = 10 * 60

    # 예약 생성 후 10분 이내인 경우 취소 허용
    if age_seconds <= correction_time:
        return True
    # 이용 시작이 24시간 전이고, 예약 생성 후 10분 초과인 경우 취소 거부
    elif until_start_seconds >= 24 * 3600 and age_seconds > correction_time:
        return False
    # 이용 시작이 24시간 이내인 경우 취소 거부
    elif until_start_seconds < 24 * 3600:
        return False
    # 일반 취소 마감이 지난 예약에 대해서도 정정 요청을 받을 수 있도록 수정
    else:
        return True
